      function check(action) {
        // last dispatch should be slow: 3
        if (action.slow === 3) { bDone(); }
      }
      const logicA = createLogic({
        type: 'FOO',
        debounce: 40,
        process({ action }, dispatch) {
          setTimeout(() => {
            dispatch({
              ...action,
              type: 'BAR'
            });
          }, 100); // delay so we can use latest
        }
      });
      const mw = createLogicMiddleware([logicA]);
      const storeFn = mw({ dispatch })(next);
      merge(
        // fast 0, 1, 2
        interval(10).pipe(
          take(3),
          map(x => ({ fast: x }))
        ),
        // slow 0, 1, 2, 3
        interval(60).pipe(
          take(4),
          delay(40),
          map(x => ({ slow: x }))
        )
      ).subscribe(x => {
        storeFn({
          ...x,
          type: 'FOO'
        });
      });
    })

