            restClient.makeRequest('GET', `/tickerMonitor`, {name:ALERT_NAME}).then((result) => {
                if (0 == result.body.length)
                {
                    done();
                    return;
                }
                let list = [];
                _.forEach(result.body, (e) => {
                    list.push(e.id);
                });
                restClient.makeRequest('DELETE', `/tickerMonitor`, {list:list}, true).then((result) => {
                    done();
                }).catch((e) => {
                    done(e);
                });
            }).catch((e) => {
                done(e);
            });
        })

